/**
 * Tutorial catalogue without lesson bodies (generated by scripts/build-tutorial-data.ts).
 * Lesson `content` is always empty here - load it with getLessonContent() from ./content.
 * The authored tutorials live in ./source.ts and are only read by the build script.
 */
import catalog from './generated/catalog.json';
import { getLessonNav } from './shared';
import type { TutorialCourse, TutorialLesson } from './types';

export const TUTORIALS = catalog.courses as TutorialCourse[];

const lessonsByCourse = new Map<string, TutorialLesson[]>(
  TUTORIALS.map((course) => {
    const bySlug = new Map(course.sections.flatMap((s) => s.lessons).map((l) => [l.slug, l]));
    const order = (catalog.lessonOrder as Record<string, string[]>)[course.slug] ?? [];
    return [course.slug, order.map((slug) => bySlug.get(slug)!).filter(Boolean)];
  }),
);

export function getTutorial(slug: string): TutorialCourse | undefined {
  return TUTORIALS.find((t) => t.slug === slug);
}

export function getTutorialLessons(courseSlug: string): TutorialLesson[] {
  return lessonsByCourse.get(courseSlug) ?? [];
}

export function getTutorialLessonNav(courseSlug: string, lessonSlug: string) {
  return getLessonNav(getTutorialLessons(courseSlug), lessonSlug);
}

export function getFirstLessonSlug(course: TutorialCourse): string | undefined {
  return course.sections[0]?.lessons[0]?.slug;
}
